final case class OrderRow(id: Long, due: LocalDate, total: BigDecimal)

final class Orders(tag: Tag) extends Table[OrderRow](tag, "orders") {
  def id = column[Long]("id")
  def due = column[LocalDate]("due")
  def total = column[BigDecimal]("total")
  def * = (id, due, total).mapTo[OrderRow]
}
val orders = TableQuery[Orders]

def overdue(asOf: LocalDate): Query[Orders, OrderRow, Seq] = orders.filter(_.due < asOf)
